mapper.update:
UPDATE mold_usage_records
usage_type = #{usageType}, scheduled_start_time = #{scheduledStartTime}, scheduled_end_time = #{scheduledEndTime}, actual_start_time = #{actualStartTime}, actual_end_time = #{actualEndTime}, applicant_name = #{applicantName}, borrower_name = #{borrowerName}, borrower_company = #{borrowerCompany}, purpose = #{purpose}, return_inspection_passed = #{inspectionPassed, typeHandler=com.zjb.mjgl.typehandler.IntegerBooleanTypeHandler}, return_remarks = #{returnRemarks}, updated_at = NOW()
WHERE id = #{id}

mapper.select:

FROM mold_usage_records r
         LEFT JOIN molds m ON r.mold_id = m.id
WHERE r.mold_id = #{moldId}
  AND r.applicant_id = #{applicantId}
ORDER BY r.created_at DESC
